```json
{
  "root_causes": [
    {
      "service": "ts-payment-service",
      "fault_kind": "process_cpu_saturated",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, service_name, metric, ROUND(AVG(value),2) avg_v, ROUND(MAX(value),2) max_v FROM abnormal_metrics_sum WHERE service_name='ts-payment-service' AND metric IN ('jvm.cpu.time','jvm.class.loaded') GROUP BY ALL UNION ALL SELECT 'norm', service_name, metric, ROUND(AVG(value),2), ROUND(MAX(value),2) FROM normal_metrics_sum WHERE service_name='ts-payment-service' AND metric IN ('jvm.cpu.time','jvm.class.loaded') GROUP BY ALL",
          "claim": "Payment JVM CPU time averaged 45 vs 0.7 normal, and class loading rose from 0 to about 6,500 during the incident."
        },
        {
          "kind": "metric",
          "sql": "SELECT date_trunc('minute', time) t, metric, ROUND(AVG(value),3) v FROM abnormal_metrics WHERE service_name='ts-payment-service' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.cpu_limit_utilization') GROUP BY ALL ORDER BY 1,2",
          "claim": "Payment pod CPU usage spiked to about 1.2-1.9 cores at 10:07-10:08 and fell back to normal, while the pod stayed under its CPU limit."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, COUNT(*) n, ROUND(AVG(duration)/1e6,1) avg_ms, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-payment-service' AND span_name IN ('PaymentController.pay','PaymentRepository.findByOrderId','SELECT ts.payment','POST /api/v1/paymentservice/payment') GROUP BY ALL",
          "claim": "Payment's own method spans slowed (PaymentController.pay p95 about 1,665 ms vs 22 ms normal) while its DB client spans stayed around 1 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code code, attr_status_code, COUNT(*) n, ROUND(AVG(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-inside-payment-service' AND span_name='POST' AND attr_span_kind='Client' GROUP BY ALL",
          "claim": "Inside-payment's calls to payment returned 503 after about 3.5 s on 8 requests, and 200 on 7 requests with slow latency."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-payment-service",
      "to": "ts-inside-payment-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, COUNT(*) n, ROUND(AVG(duration)/1e6,1) avg_ms, ROUND(MAX(duration)/1e6,1) max_ms FROM abnormal_traces WHERE (service_name='ts-payment-service' AND span_name='POST /api/v1/paymentservice/payment') OR (service_name='ts-inside-payment-service' AND span_name='POST /api/v1/inside_pay_service/inside_payment' AND attr_span_kind='Server') GROUP BY ALL",
          "claim": "Payment's payment endpoint slowed to about 669 ms avg (max 2,283 ms), and inside-payment's server calls failed with 500 or ran slow."
        }
      ]
    },
    {
      "from": "ts-inside-payment-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code code, COUNT(*) n, ROUND(AVG(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='POST /api/v1/inside_pay_service/inside_payment' GROUP BY ALL",
          "claim": "Ui-dashboard's inside_payment requests averaged about 5,788 ms in the incident vs 275 ms normal, due to inside-payment's failures."
        }
      ]
    }
  ]
}
